"""Inventory reporting primitives used by a small command-line application."""

from collections.abc import Iterable
from dataclasses import dataclass


@dataclass(frozen=True)
class Item:
    sku: str
    quantity: int
    discontinued: bool = False


def inventory_summary(
    items: Iterable[Item], include_discontinued: bool = False
) -> dict[str, int]:
    """Return the count and units for currently available inventory."""
    available = [
        item
        for item in items
        if item.quantity > 0 and (include_discontinued or not item.discontinued)
    ]
    return {"count": len(available), "units": sum(item.quantity for item in available)}


