from src.inventory import Item, inventory_summary


def test_default_excludes_discontinued_items():
    assert inventory_summary(
        [Item("active", 2), Item("old", 3, discontinued=True)]
    ) == {
        "count": 1,
        "units": 2,
    }


def test_include_discontinued_accepts_any_iterable_and_excludes_nonpositive_stock():
    items = (
        item
        for item in [
            Item("active", 2),
            Item("old", 3, discontinued=True),
            Item("zero", 0, discontinued=True),
            Item("negative", -1),
        ]
    )

    assert inventory_summary(items, include_discontinued=True) == {
        "count": 2,
        "units": 5,
    }


